mapper.select:
select (select fe.NAME from fnd_employee fe where fe.EMPLOYEE_ID = lah.MODIFY_PERSON) MODIFY_PERSON_N,
(select scvb.meaning as value_name from sys_code_value_b scvb, sys_code_b scb where scb.code = 'LEASE.ASSET_STATE' and scb.code_id = scvb.code_id and scvb.enabled_flag = 'Y' and scvb.value = lah.ASSET_STATUS )ASSET_STATUS_N,
lah.* from lease_asset_hd lah
1=1
and lah.ASSET_NUMBER = #{assetNumber}
and lah.ASSET_HD_ID = #{assetHdId}
and lah.MODIFY_DATE between #{modifyDateFrom} and #{modifyDateTo}
and lah.DESCRIPTION = #{description}
order by lah.ASSET_NUMBER desc

select lah.ASSET_STATUS, lah.*, (select fe.NAME from fnd_employee fe where fe.EMPLOYEE_ID = lah.MODIFY_PERSON) MODIFY_PERSON_N, (select fou.UNIT_NAME from fnd_org_unit fou where fou.UNIT_ID = lah.MODIFY_UNIT) MODIFY_UNIT_N from lease_asset_hd lah
lah.ASSET_HD_ID = #{assetHdId}
and lah.MODIFY_DATE between #{modifyDateFrom} and #{modifyDateTo}
and lah.DESCRIPTION = #{description}
